from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
INDEX = ROOT / "index.html"

SCRIPT = r'''<script>(()=>{const KEY='lalastar-language';const btn=document.getElementById('langBtn');const nav=document.querySelector('.links');const translations={ar:{eyebrow:'شركة لألأة النجوم التجارية · المملكة العربية السعودية',heroTitle:'تجارة المواد الغذائية بالجملة منذ 1993',heroLead:'من الدمام إلى الأحساء، مسيرة تجارية بدأت عام 1993 وتوسعت مع الوقت في أنشطة البلاستيك والحلويات والوجبات الخفيفة.',aboutTitle:'شركة لها مسار واضح',aboutLead:'تأسست شركة لألأة النجوم التجارية في الدمام عام 1993 في مجال بيع المواد الغذائية بالجملة، ثم توسعت أعمالها لتشمل أنشطة تجارية أخرى تحت مظلة الشركة.',storyTitle:'من الدمام بدأت الرحلة',storyText:'الدمام هي الفرع الرئيسي للشركة. وفي عام 2018 تم افتتاح فرع الأحساء، ثم توسعت الأنشطة في البلاستيك والحلويات والوجبات الخفيفة في مواقعها المخصصة.',businessTitle:'أنشطتنا',businessLead:'أنشطة مستقلة تحت مظلة الشركة، مع الحفاظ على وضوح كل نشاط وموقعه.',foodTitle:'المواد الغذائية بالجملة',foodText:'النشاط الرئيسي للشركة.',plasticTitle:'المنتجات البلاستيكية',plasticText:'منتجات البلاستيك والأدوات المنزلية.',sweetsTitle:'الحلويات والسناكات',sweetsText:'حلويات ووجبات خفيفة.',locationsTitle:'فروعنا ومواقعنا',locationsLead:'المواد الغذائية متوفرة في الدمام والأحساء، بينما الحلويات والوجبات الخفيفة في الأحساء فقط.',dammamTitle:'المواد الغذائية — الدمام',dammamText:'الفرع الرئيسي للشركة منذ 1993.',ahsaTitle:'المواد الغذائية — الأحساء',ahsaText:'فرع الأحساء الذي افتتح عام 2018.',map:'فتح الموقع على الخرائط ↗',contactTitle:'تواصل مع شركة لألأة النجوم التجارية',contactText:'للاستفسارات والتواصل التجاري، يمكنكم التواصل معنا عبر الهاتف أو البريد الإلكتروني.',phone:'الهاتف',email:'البريد الإلكتروني',skip:'تخطي إلى المحتوى الرئيسي'},en:{eyebrow:'LALA STAR TRADING CO. · KINGDOM OF SAUDI ARABIA',heroTitle:'Wholesale Food Trading Since 1993',heroLead:'From Dammam to Al-Ahsa, a commercial journey that began in 1993 and expanded into plastics, sweets, and snacks.',aboutTitle:'A Company With a Clear Path',aboutLead:'LALA STAR TRADING CO. was established in Dammam in 1993 in wholesale food trading, then expanded into additional activities under the company.',storyTitle:'The Journey Began in Dammam',storyText:'Dammam is the company’s main branch. In 2018, the Al-Ahsa branch opened, followed by expansion into plastics, sweets, and snacks at their designated locations.',businessTitle:'Our Businesses',businessLead:'Independent activities under one company, with each activity and location clearly defined.',foodTitle:'Wholesale Food Products',foodText:'The company’s core activity.',plasticTitle:'Plastic Products',plasticText:'Plastic products and household supplies.',sweetsTitle:'Sweets & Snacks',sweetsText:'Sweets and snack products.',locationsTitle:'Our Branches & Locations',locationsLead:'Food products are available in Dammam and Al-Ahsa, while sweets and snacks are available in Al-Ahsa only.',dammamTitle:'Food Products — Dammam',dammamText:'The company’s main branch since 1993.',ahsaTitle:'Food Products — Al-Ahsa',ahsaText:'The Al-Ahsa branch opened in 2018.',map:'Open in Maps ↗',contactTitle:'Contact LALA STAR TRADING CO.',contactText:'For inquiries and business communication, contact us by phone or email.',phone:'Phone',email:'Email',skip:'Skip to main content'}};const set=(s,v)=>{const e=document.querySelector(s);if(e)e.textContent=v};const apply=lang=>{const t=translations[lang];document.documentElement.lang=lang;document.documentElement.dir=lang==='en'?'ltr':'rtl';document.title=lang==='en'?'LALA STAR TRADING CO. | Wholesale Food Trading':'شركة لألأة النجوم التجارية | LALA STAR TRADING CO.';const desc=document.querySelector('meta[name="description"]');if(desc)desc.content=lang==='en'?'LALA STAR TRADING CO. — wholesale food trading since 1993, with plastic products, sweets and snacks.':'شركة لألأة النجوم التجارية — تجارة المواد الغذائية بالجملة منذ 1993، مع أنشطة البلاستيك والحلويات والوجبات الخفيفة.';if(btn){btn.textContent=lang==='en'?'AR':'EN';btn.setAttribute('aria-label',lang==='en'?'Change language':'تغيير اللغة')}set('.eyebrow',t.eyebrow);set('.hero h1',t.heroTitle);set('.hero .lead',t.heroLead);set('#about h2',t.aboutTitle);set('#about .head p',t.aboutLead);set('.story-copy h3',t.storyTitle);set('.story-copy>p',t.storyText);set('#businesses h2',t.businessTitle);set('#businesses .head p',t.businessLead);set('.business:nth-child(1) h3',t.foodTitle);set('.business:nth-child(1) p',t.foodText);set('.business:nth-child(2) h3',t.plasticTitle);set('.business:nth-child(2) p',t.plasticText);set('.business:nth-child(3) h3',t.sweetsTitle);set('.business:nth-child(3) p',t.sweetsText);set('#branches h2',t.locationsTitle);set('#branches .head p',t.locationsLead);set('.branch:nth-child(1) h3',t.dammamTitle);set('.branch:nth-child(1) p',t.dammamText);set('.branch:nth-child(2) h3',t.ahsaTitle);set('.branch:nth-child(2) p',t.ahsaText);document.querySelectorAll('.map').forEach(e=>e.textContent=t.map);set('#contact h2',t.contactTitle);set('#contact p',t.contactText);document.querySelectorAll('.card span').forEach((e,i)=>e.textContent=i===0?t.phone:t.email);const skip=document.querySelector('.skip-link');if(skip){skip.textContent=t.skip;skip.setAttribute('aria-label',t.skip)}nav?.querySelectorAll('a').forEach(a=>a.textContent=lang==='en'?a.dataset.en:a.dataset.ar)};let lang=localStorage.getItem(KEY)==='en'?'en':'ar';btn?.addEventListener('click',()=>{lang=lang==='en'?'ar':'en';localStorage.setItem(KEY,lang);apply(lang)});apply(lang)})();</script>'''

html = INDEX.read_text(encoding='utf-8')
html = re.sub(r'<script>const btn=document\.getElementById\(\'langBtn\'\);.*?</script>', SCRIPT, html, count=1, flags=re.DOTALL)
if "lalastar-language" not in html:
    html = html.replace('</body>', SCRIPT + '</body>', 1)
if "localStorage.setItem(KEY,lang)" not in html:
    raise RuntimeError("Language persistence was not installed")
INDEX.write_text(html, encoding='utf-8')
